from collections import defaultdict

class Solution:
    def minPath(self, grid, k):
        # Initialize the dictionary to store the minimum path lengths
        dp = defaultdict(lambda: float('inf'))

        # Iterate over all possible starting points
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                # If the current cell has already been visited, skip it
                if grid[i][j] == 0:
                    continue

                # Calculate the minimum path length ending at this cell
                dp[(i, j)] = min(dp[(i-1, j)], dp[(i+1, j)], dp[(i, j-1)], dp[(i, j+1)]) + 1

        # Find the minimum path length for each cell
        return [dp[(i, j)] for i in range(len(grid)) for j in range(len(grid[0]))]

